def new_transform(grid):
    h,w=len(grid),len(grid[0])
    counts={v:sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    bg=max(counts,key=counts.get)
    marker=min((v for v in counts if v not in (bg,0)), key=counts.get)
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==marker]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    shape=[(r-r0,c-c0) for r,c in pts]
    sh=max(r for r,c in shape); sw=max(c for r,c in shape)
    out=[row[:] for row in grid]
    for r in range(h-sh):
        for c in range(w-sw):
            if all(grid[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape: out[r+dr][c+dc]=marker
    return out

